    'hub.region.middle_east.intro': 'Länder des Nahen Ostens, geordnet nach Sicherheitsbewertung. Sehen Sie, wie jedes Land der Region abschneidet.',
    'hub.solo_travelers.title': 'Sicherste Länder für Alleinreisende (2026)',
